<?php
session_start(); require_once __DIR__.'/../php/sd_authorization.php'; sdRequireRole('technician');
require_once __DIR__.'/../php/conexao.php'; require_once __DIR__.'/../php/sd_service.php';
function reportEsc($x): string {return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
$minutes=(int)($_GET['inactive']??30);if(!in_array($minutes,[15,30,60,180,1440],true))$minutes=30;
$device=trim((string)($_GET['device']??''));$device=mb_substr($device,0,64);$pattern='%'.addcslashes($device,'%_\\').'%';
$devices=[];$events=[];$summary=[];$error='';
try{sdSchema($conexao);require_once __DIR__.'/../php/iot_service.php';
 if(!iotTableExists($conexao,'iot_devices')||!iotTableExists($conexao,'iot_telemetry'))throw new RuntimeException('Tabelas de telemetria não instaladas');
 $st=$conexao->prepare("SELECT d.device_id,d.name,d.location,d.status,d.last_seen,COUNT(t.id) readings24, SUM(t.quality_status='alerta') alerts24,MAX(t.captured_at) latest_reading, CASE WHEN d.last_seen IS NULL OR d.last_seen < DATE_SUB(NOW(),INTERVAL ? MINUTE) THEN 1 ELSE 0 END inactive FROM iot_devices d LEFT JOIN iot_telemetry t ON t.device_id=d.device_id AND t.captured_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) WHERE (?='' OR d.device_id LIKE ? OR d.name LIKE ?) GROUP BY d.id,d.device_id,d.name,d.location,d.status,d.last_seen ORDER BY inactive DESC,d.last_seen ASC LIMIT 150");$st->bind_param('isss',$minutes,$device,$pattern,$pattern);$st->execute();$devices=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
 $st=$conexao->prepare("SELECT e.device_id,e.outcome,e.created_at,r.name rule_name,t.protocol,t.status ticket_status FROM sd_iot_rule_events e JOIN sd_iot_rules r ON r.id=e.rule_id LEFT JOIN sd_tickets t ON t.id=e.ticket_id WHERE (?='' OR e.device_id LIKE ?) ORDER BY e.id DESC LIMIT 100");$st->bind_param('ss',$device,$pattern);$st->execute();$events=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
 $summary=['total'=>count($devices),'inactive'=>count(array_filter($devices,static fn($d)=>(int)$d['inactive']===1)),'alerts'=>array_sum(array_map(static fn($d)=>(int)$d['alerts24'],$devices))];
}catch(Throwable $e){error_log('iot monitoring: '.$e->getMessage());$error='Não foi possível consultar dispositivos e incidentes. Instale as tabelas IoT e do Service Desk.';}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CONFINTER — Monitoramento IoT</title><link rel="stylesheet" href="../assets/css/sd.css"><link rel="stylesheet" href="../assets/css/confinter-sd-refinement.css"><link rel="stylesheet" href="assets/css/admin-ui.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><link rel="stylesheet" href="assets/css/confinter-reporting.css"></head><body><?php include __DIR__.'/navbar.php';?><div class="page-wrapper"><main class="sd-wrap sd-admin-surface"><header><a href="service-desk.php">← Service Desk</a><h1>Monitoramento de dispositivos e incidentes</h1></header><p>Estado de comunicação calculado por <strong>última leitura recebida</strong>. “Sem comunicação” não modifica o status cadastrado. O cadastro contém apenas dispositivos já registrados, portanto não detecta sensores nunca cadastrados.</p><form method="get" class="report-filters"><label>Dispositivo <input name="device" value="<?=reportEsc($device)?>" maxlength="64" placeholder="ID ou nome"></label><label>Sem comunicação após <select name="inactive"><?php foreach([15,30,60,180,1440] as $n):?><option value="<?=$n?>" <?=$minutes===$n?'selected':''?>><?=$n?> minutos</option><?php endforeach;?></select></label><button>Filtrar</button></form><?php if($error):?><p class="notice" role="alert"><?=reportEsc($error)?></p><?php else:?><div class="sd-metrics"><article><strong><?=reportEsc($summary['total'])?></strong><span>Dispositivos exibidos (até 150)</span></article><article><strong><?=reportEsc($summary['inactive'])?></strong><span>Sem comunicação recente</span></article><article><strong><?=reportEsc($summary['alerts'])?></strong><span>Leituras em alerta (24 h)</span></article></div><section class="sd-card"><h2>Estado por dispositivo</h2><div class="sd-table-scroll"><table><thead><tr><th>Dispositivo</th><th>Status cadastrado</th><th>Comunicação</th><th>Última conexão</th><th>Leituras (24 h)</th><th>Alertas (24 h)</th></tr></thead><tbody><?php foreach($devices as $d):?><tr><td><strong><a href="iot-dispositivo.php?device=<?=rawurlencode((string)$d['device_id'])?>"><?=reportEsc($d['device_id'])?></a></strong><p><?=reportEsc($d['name']??'')?> · <?=reportEsc($d['location']??'')?></p></td><td><?=reportEsc($d['status'])?></td><td><strong class="<?=((int)$d['inactive']===1)?'report-alert':'report-ok'?>"><?=((int)$d['inactive']===1)?'Sem comunicação recente':'Comunicação recente'?></strong></td><td><?=reportEsc($d['last_seen']??'Nunca')?></td><td><?=reportEsc($d['readings24'])?></td><td><?=reportEsc($d['alerts24'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$devices):?><p>Nenhum dispositivo encontrado.</p><?php endif;?></section><section class="sd-card"><h2>Histórico de regras e incidentes (100 eventos mais recentes)</h2><p>Eventos “suppressed” são condições detectadas sem novo chamado, normalmente por cooldown ou incidente aberto existente.</p><div class="sd-table-scroll"><table><thead><tr><th>Data</th><th>Dispositivo</th><th>Regra</th><th>Resultado</th><th>Chamado</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?=reportEsc($e['created_at'])?></td><td><?=reportEsc($e['device_id'])?></td><td><?=reportEsc($e['rule_name'])?></td><td><?=reportEsc($e['outcome']==='created'?'Chamado criado':'Suprimido')?></td><td><?=reportEsc($e['protocol']??'—')?> <?=reportEsc($e['ticket_status']??'')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></div><?php include __DIR__.'/footer.php'; ?></body></html>